%
% spec-hook-gates-mute.tex -- scratch, not committed.
%
% Decoupled reachability demonstration for docs/spec-hook-gates.tex
% Validation section: GateU/InitU/MuteSkipU/IdleU, checking whether
% the CURRENT subagent_start.go:599-605 mute-skip semantics can reach
% the silent-disabled state. Deliberately not part of the checked
% namespace of the committed document -- see that document's
% "Errata: why this schema is not checked against GateState" for why.
%
\documentclass[a4paper,10pt,fleqn]{article}
\usepackage[margin=1in]{geometry}
\usepackage{fuzz}
\begin{document}

\begin{zed}
ZBOOL ::= ztrue | zfalse
\end{zed}

\begin{schema}{GateU}
verifierOfOpenMission : ZBOOL \\
decided : ZBOOL \\
gateApplied : ZBOOL \\
diagnosticEmitted : ZBOOL
\end{schema}

\begin{schema}{InitU}
GateU' \\
verifierOfOpenMission? : ZBOOL
\where
verifierOfOpenMission' = verifierOfOpenMission? \\
decided' = zfalse \\
gateApplied' = zfalse \\
diagnosticEmitted' = zfalse
\end{schema}

\begin{schema}{MuteSkipU}
\Delta GateU
\where
decided = zfalse \\
decided' = ztrue \\
gateApplied' = zfalse \\
diagnosticEmitted' = zfalse \\
verifierOfOpenMission' = verifierOfOpenMission
\end{schema}

\begin{schema}{IdleU}
\Xi GateU
\where
\lnot (decided = ztrue \land verifierOfOpenMission = ztrue
       \land gateApplied = zfalse \land diagnosticEmitted = zfalse)
\end{schema}

\end{document}

